function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));if(started)$('mobileControls').style.display=innerWidth<=700?'block':'none';}
function bindStick(){const el=$('stick');let pid=null;const move=e=>{if(pid!==e.pointerId)return;const r=el.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),k=Math.min(1,len/40);joystick.x=dx/(len||1)*k;joystick.y=dy/(len||1)*k;};el.addEventListener('pointerdown',e=>{pid=e.pointerId;el.setPointerCapture(pid);move(e);});el.addEventListener('pointermove',move);el.addEventListener('pointerup',e=>{if(e.pointerId===pid){pid=null;joystick.x=joystick.y=0;}});let lookId=null,lastX=0,lastY=0;renderer?.domElement?.addEventListener('touchstart',()=>{});document.addEventListener('touchstart',e=>{if(e.touches.length&&e.touches[0].clientX>innerWidth*.45){lookId=e.touches[0].identifier;lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;}},{passive:true});document.addEventListener('touchmove',e=>{if(lookId===null)return;for(const t of e.touches)if(t.identifier===lookId){yaw-=(t.clientX-lastX)*.006;pitch=THREE.MathUtils.clamp(pitch-(t.clientY-lastY)*.004,-.5,.3);lastX=t.clientX;lastY=t.clientY;}},{passive:true});document.addEventListener('touchend',e=>{for(const t of e.changedTouches)if(t.identifier===lookId)lookId=null;});}
function fire(){if(!started||ended||state.reload>0||state.fireCD>0)return;if(state.ammo<=0){reload();return;}state.ammo--;state.fireCD=state.overclock>0?.105:.19;$('ammo').innerHTML=state.ammo+'<span> / '+state.maxAmmo+'</span>';const dir=cameraDirection();const origin=camera.position.clone();const target=new THREE.Vector3();const ray=new THREE.Raycaster(origin,dir,0,45);const enemyBox=new THREE.Box3().setFromObject(enemy);const intersects=ray.intersectObject(enemy,true);const hit=intersects.length>0&&intersects[0].distance<45;let endpoint=origin.clone().addScaledVector(dir,38);if(hit){endpoint=intersects[0].point;const coreHit=endpoint.distanceTo(enemy.position.clone().add(V(0,1.4,0)))<.7;damageEnemy(state.overclock>0?24:coreHit?30:20);$('hitmarker').classList.add('show');setTimeout(()=>$('hitmarker').classList.remove('show'),100);state.ult=Math.min(100,state.ult+7);updateUlt();}spawnTracer(origin,endpoint,0x68fff4);const gunTip=player.localToWorld(V(.34,1.25,1.05));spawnGlow(gunTip,0x68fff4,.3);if(state.ammo===0)setTimeout(reload,250);}
function cameraDirection(){return V(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)).normalize();}
function reload(){if(state.ammo===state.maxAmmo||state.reload>0)return;state.reload=1.15;$('ammo').innerHTML='<span>RELOAD</span>';setTimeout(()=>{if(!ended){state.ammo=state.maxAmmo;state.reload=0;$('ammo').innerHTML=state.ammo+'<span> / '+state.maxAmmo+'</span>'; }},1150);}
function damageEnemy(n){if(ended)return;state.enemyHp=Math.max(0,state.enemyHp-n);$('enemyHealth').style.width=state.enemyHp/state.maxEnemyHp*100+'%';state.hit=.15;enemy.userData.flash=.12;if(state.enemyHp<=0){state.score++;$('score').textContent=state.score;finish(true);}}
function damagePlayer(n){if(ended)return;state.hp=Math.max(0,state.hp-n);$('healthNum').textContent=state.hp;$('healthFill').style.width=state.hp/state.maxHp*100+'%';$('damageFlash').classList.add('show');setTimeout(()=>$('damageFlash').classList.remove('show'),130);state.shake=.18;if(state.hp<=0){state.enemyScore++;$('enemyScore').textContent=state.enemyScore;finish(false);}}
function dash(){if(!started||ended||state.dash>0)return;state.dash=.95;const dir=V(-Math.sin(yaw),0,-Math.cos(yaw));if(keys.KeyS||joystick.y<-.3)dir.negate();if(keys.KeyA||joystick.x<-.3)dir.set(-Math.cos(yaw),0,Math.sin(yaw));if(keys.KeyD||joystick.x>.3)dir.set(Math.cos(yaw),0,-Math.sin(yaw));player.position.addScaledVector(dir,3.8);player.position.x=THREE.MathUtils.clamp(player.position.x,-15.5,15.5);player.position.z=THREE.MathUtils.clamp(player.position.z,-15.5,15.5);spawnBurst(player.position.clone().add(V(0,1,0)),0x4efff1);updateAbilities();}
function pulse(){if(!started||ended||state.pulse>0)return;state.pulse=5;const d=enemy.position.distanceTo(player.position);if(d<8){damageEnemy(35);const away=enemy.position.clone().sub(player.position).setY(0).normalize();enemy.position.addScaledVector(away,2.4);state.ult=Math.min(100,state.ult+10);updateUlt();}spawnBurst(player.position.clone().add(V(0,1,0)),0x4efff1);updateAbilities();}
function ultimate(){if(!started||ended||state.ult<100)return;state.ult=0;state.overclock=7;player.scale.setScalar(1.13);updateUlt();$('toast').textContent='OVERCLOCK // ACTIVE';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),950);}
function updateAbilities(){ $('dashIcon').classList.toggle('ready',state.dash<=0);$('pulseIcon').classList.toggle('ready',state.pulse<=0);}
function updateUlt(){$('ultText').textContent=Math.floor(state.ult)+'%';$('ultRing').classList.toggle('full',state.ult>=100);}
function spawnTracer(a,b,color){const d=b.clone().sub(a);const ob=mesh(new THREE.CylinderGeometry(.012,.012,d.length(),5),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85}));ob.position.copy(a).add(b).multiplyScalar(.5);ob.quaternion.setFromUnitVectors(V(0,1,0),d.normalize());effects.push({object:ob,life:.11,max:.11});}
function spawnGlow(p,color,size){const o=mesh(new THREE.SphereGeometry(size,8,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));o.position.copy(p);effects.push({object:o,life:.12,max:.12});}
function spawnBurst(p,color){const ring=mesh(new THREE.TorusGeometry(.35,.035,6,36),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.position.copy(p);ring.rotation.x=Math.PI/2;effects.push({object:ring,life:.5,max:.5,expand:true});}
function finish(win){if(ended)return;ended=true;document.exitPointerLock?.();$('endScreen').style.display='flex';$('result').textContent=win?'VICTORY':'DEFEAT';$('result').className='result '+(win?'win':'loss');$('resultSub').textContent=win?'THE CIRCUIT IS YOURS.':'VEX OWNS THIS ROUND. RESET AND RE-ENGAGE.';}

