64: function clampArena(p,r=15.2){p.x=THREE.MathUtils.clamp(p.x,-r,r);p.z=THREE.MathUtils.clamp(p.z,-r,r);}
65: function updatePlayer(dt){let x=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joystick.x,z=(keys.KeyS?1:0)-(keys.KeyW?1:0)+joystick.y;const v=V(x,0,z);if(v.lengthSq()>1)v.normalize();const forward=V(-Math.sin(yaw),0,-Math.cos(yaw)),right=V(Math.cos(yaw),0,-Math.sin(yaw));const movement=forward.multiplyScalar(-v.z).add(right.multiplyScalar(v.x));const speed=state.overclock>0?7.4:5.7;player.position.addScaledVector(movement,speed*dt);clampArena(player.position);if(movement.lengthSq()>.01){player.rotation.y=Math.atan2(movement.x,movement.z);player.userData.step=(player.userData.step||0)+dt*12;player.position.y=Math.abs(Math.sin(player.userData.step))*.045;}else{player.position.y=0;player.rotation.y=yaw+Math.PI;}if(keys.Space&&player.position.y===0){player.userData.jump=1;}if(player.userData.jump>0){player.userData.jump-=dt;player.position.y=Math.sin((1-player.userData.jump)*Math.PI)*.8;}camera.position.copy(player.position).add(V(Math.sin(yaw)*5.3+Math.cos(yaw)*1.05,2.65+Math.sin(pitch)*1.5,Math.cos(yaw)*5.3-Math.sin(yaw)*1.05));const look=player.position.clone().addScaledVector(cameraDirection(),24);camera.lookAt(look);if(state.fireCD>0)state.fireCD-=dt;if(state.reload>0){}if(state.dash>0)state.dash-=dt;if(state.pulse>0)state.pulse-=dt;if(state.overclock>0){state.overclock-=dt;if(state.overclock===0)player.scale.setScalar(1);}updateAbilities();}
66: function updateEnemy(dt){if(ended)return;const delta=player.position.clone().sub(enemy.position);delta.y=0;const dist=delta.length();if(dist>6.8){enemy.position.addScaledVector(delta.normalize(),dt*2.15);}else if(dist<4.2){enemy.position.addScaledVector(delta.normalize(),-dt*1.6);}const strafe=V(-delta.z,0,delta.x).normalize().multiplyScalar(Math.sin(performance.now()*.00075)*dt*1.2);enemy.position.add(strafe);clampArena(enemy.position,14.8);enemy.rotation.y=Math.atan2(delta.x,delta.z);enemy.userData.bob=(enemy.userData.bob||0)+dt*5;enemy.position.y=Math.abs(Math.sin(enemy.userData.bob))*.045;if(enemy.userData.flash>0){enemy.userData.flash-=dt;enemy.children[0].material.emissiveIntensity=1.8;}else enemy.children[0].material.emissiveIntensity=.33;state.enemyFire-=dt;if(state.enemyFire<=0&&dist<17){state.enemyFire=1.15+Math.random()*.55;const start=enemy.position.clone().add(V(0,1.35,0)),end=player.position.clone().add(V(0,1.2,0));spawnTracer(start,end,0xff6588);damagePlayer(7);}}
67: function updateEffects(dt){for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.expand){e.object.scale.setScalar(1+(e.max-e.life)*7);e.object.material.opacity=Math.max(0,e.life/e.max);}else e.object.material.opacity=Math.max(0,e.life/e.max);if(e.life<=0){scene.remove(e.object);e.object.geometry.dispose();e.object.material.dispose();effects.splice(i,1);}}}
